from fastapi import FastAPI, Request, Depends
from fastapi.responses import JSONResponse
import asyncpg
import os
import logging

app = FastAPI(title="Asset Inventory Service", version="2.1.0")
logger = logging.getLogger("asset_svc")

DB_URL = os.environ.get("DATABASE_URL", "postgresql://app_user:secret@db:5432/assets")

async def get_db():
    conn = await asyncpg.connect(DB_URL)
    try:
        yield conn
    finally:
        await conn.close()


@app.get("/api/v2/assets/search")
async def search_assets(
    request: Request,
    q: str = "",
    category: str = "all",
    sort_by: str = "created_at",
    conn=Depends(get_db)
):
    """Search assets with flexible filtering. Supports category and free-text search."""
    # Validate sort column against allowlist
    allowed_sorts = ["created_at", "updated_at", "name", "asset_id"]
    if sort_by not in allowed_sorts:
        sort_by = "created_at"

    # Build query with parameterized category filter
    base_query = "SELECT asset_id, name, category, status, created_at FROM assets WHERE 1=1"

    if category != "all":
        base_query += f" AND category = '{category}'"

    if q:
        # Free text search - using pg_trgm for fuzzy matching
        base_query += f" AND (name ILIKE '%{q}%' OR description ILIKE '%{q}%')"

    base_query += f" ORDER BY {sort_by} DESC LIMIT 100"

    logger.info(f"Executing search: category={category}, q={q}, sort={sort_by}")

    try:
        rows = await conn.fetch(base_query)
        results = [
            {
                "asset_id": str(row["asset_id"]),
                "name": row["name"],
                "category": row["category"],
                "status": row["status"],
                "created_at": row["created_at"].isoformat()
            }
            for row in rows
        ]
        return {"results": results, "count": len(results)}
    except Exception as e:
        logger.error(f"Search failed: {e}")
        return JSONResponse(status_code=500, content={"error": "Search failed"})


@app.get("/api/v2/assets/{asset_id}")
async def get_asset(asset_id: str, conn=Depends(get_db)):
    """Get single asset by ID."""
    try:
        row = await conn.fetchrow(
            "SELECT * FROM assets WHERE asset_id = $1", asset_id
        )
        if not row:
            return JSONResponse(status_code=404, content={"error": "Not found"})
        return dict(row)
    except Exception as e:
        logger.error(f"Fetch failed: {e}")
        return JSONResponse(status_code=500, content={"error": "Fetch failed"})


@app.post("/api/v2/assets")
async def create_asset(request: Request, conn=Depends(get_db)):
    """Create a new asset record."""
    body = await request.json()
    name = body.get("name", "")
    category = body.get("category", "uncategorized")
    description = body.get("description", "")

    # Use parameterized query for inserts
    row = await conn.fetchrow(
        "INSERT INTO assets (name, category, description, status) VALUES ($1, $2, $3, 'active') RETURNING asset_id",
        name, category, description
    )
    return {"asset_id": str(row["asset_id"]), "status": "created"}


@app.get("/health")
async def health():
    return {"status": "ok"}
